#!/usr/bin/env node
/**
 * Seeds the local stack with demo venues, events and shows through the real APIs
 * (Keycloak admin token -> API gateway -> catalog-service). Seat maps are generated by
 * seat-inventory-service from the ShowScheduled Kafka event a few seconds later.
 *
 *   npm run seed
 *   GATEWAY_URL=http://localhost:8080 KEYCLOAK_URL=http://localhost:8180 npm run seed
 *
 * Local development only: uses the checked-in admin/admin123 demo account via the password grant.
 */
const GATEWAY = process.env.GATEWAY_URL ?? 'http://localhost:8080';
const KEYCLOAK = process.env.KEYCLOAK_URL ?? 'http://localhost:8180';
const REALM = process.env.KEYCLOAK_REALM ?? 'bmtickets';
const USER = process.env.ADMIN_USER ?? 'admin';
const PASS = process.env.ADMIN_PASSWORD ?? 'admin123';
const DAYS = Number(process.env.SEED_DAYS ?? 4);

const VENUES = [
  { name: 'PVR Phoenix Palladium', city: 'Mumbai', address: 'Lower Parel', capacity: 200 },
  { name: 'INOX Nariman Point', city: 'Mumbai', address: 'Nariman Point', capacity: 180 },
  { name: 'NSCI Dome', city: 'Mumbai', address: 'Worli', capacity: 240 },
  { name: 'PVR Select Citywalk', city: 'Delhi', address: 'Saket', capacity: 200 },
  { name: 'Jawaharlal Nehru Stadium', city: 'Delhi', address: 'Pragati Vihar', capacity: 240 },
  { name: 'PVR Orion Mall', city: 'Bengaluru', address: 'Rajajinagar', capacity: 200 },
];

const EVENTS = [
  { title: 'Interstellar (Re-release)', category: 'MOVIE', language: 'English', durationMinutes: 169, description: 'A team of explorers travel through a wormhole in space in an attempt to ensure humanity\'s survival.' },
  { title: 'Midnight Express Lane', category: 'MOVIE', language: 'Hindi', durationMinutes: 142, description: 'A Mumbai cab driver gets one night to deliver a mysterious package across the city.' },
  { title: 'The Last Monsoon', category: 'MOVIE', language: 'Tamil', durationMinutes: 155, description: 'Three generations of a fishing family face the storm of the century.' },
  { title: 'Neon Kingdom', category: 'MOVIE', language: 'English', durationMinutes: 128, description: 'An animated adventure through a city that only exists after dark.' },
  { title: 'Orbit: The Sky Tour', category: 'CONCERT', language: 'Hindi', durationMinutes: 180, description: 'An arena-scale live show with a full orchestra and drone light display.' },
  { title: 'Indie Nights Live', category: 'CONCERT', language: 'English', durationMinutes: 150, description: 'Five indie bands, one stage, all night.' },
  { title: 'Champions League T20 Final', category: 'SPORTS', language: null, durationMinutes: 240, description: 'The season decider under lights.' },
  { title: 'Late Night Laughs', category: 'COMEDY', language: 'English', durationMinutes: 90, description: 'Stand-up from the country\'s sharpest new voices.' },
  { title: 'The Glass Menagerie', category: 'THEATRE', language: 'English', durationMinutes: 130, description: 'A modern staging of the classic memory play.' },
];

const CINEMA_LAYOUT = {
  priceByCategory: { SILVER: 220, GOLD: 350, RECLINER: 750 },
  sections: [
    { category: 'SILVER', rows: ['A', 'B', 'C'], seatsPerRow: 16 },
    { category: 'GOLD', rows: ['D', 'E', 'F', 'G'], seatsPerRow: 16 },
    { category: 'RECLINER', rows: ['H'], seatsPerRow: 10 },
  ],
};
const ARENA_LAYOUT = {
  priceByCategory: { GENERAL: 999, PREMIUM: 2499, VIP: 4999 },
  sections: [
    { category: 'GENERAL', rows: ['A', 'B', 'C', 'D'], seatsPerRow: 20 },
    { category: 'PREMIUM', rows: ['E', 'F'], seatsPerRow: 16 },
    { category: 'VIP', rows: ['G'], seatsPerRow: 10 },
  ],
};

async function token() {
  const res = await fetch(`${KEYCLOAK}/realms/${REALM}/protocol/openid-connect/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'password', client_id: 'bmtickets-web', username: USER, password: PASS }),
  });
  if (!res.ok) throw new Error(`Keycloak token request failed: ${res.status} ${await res.text()}`);
  return (await res.json()).access_token;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function post(path, body, accessToken, attempt = 1) {
  const res = await fetch(`${GATEWAY}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify(body),
  });
  if ((res.status === 429 || res.status === 503) && attempt < 5) {
    await sleep(Number(res.headers.get('Retry-After') ?? 1) * 1000);
    return post(path, body, accessToken, attempt + 1);
  }
  if (!res.ok) throw new Error(`POST ${path} -> ${res.status} ${await res.text()}`);
  return res.json();
}

function startTime(dayOffset, hour, minute) {
  const d = new Date();
  d.setDate(d.getDate() + dayOffset);
  d.setHours(hour, minute, 0, 0);
  return d.toISOString();
}

async function main() {
  console.log(`Seeding ${GATEWAY} as ${USER} ...`);
  const accessToken = await token();

  const venues = [];
  for (const v of VENUES) {
    const { id } = await post('/api/v1/catalog/venues', v, accessToken);
    venues.push({ ...v, id });
    console.log(`  venue  ${v.name} (${v.city})`);
  }

  const events = [];
  for (const e of EVENTS) {
    const { id } = await post('/api/v1/catalog/events', { ...e, language: e.language ?? undefined }, accessToken);
    events.push({ ...e, id });
    console.log(`  event  ${e.title}`);
  }

  const cinemas = venues.filter((v) => /PVR|INOX/.test(v.name));
  const arenas = venues.filter((v) => !/PVR|INOX/.test(v.name));
  const slots = [[10, 30], [14, 15], [18, 0], [21, 45]];
  let shows = 0;
  for (const event of events) {
    const isMovie = event.category === 'MOVIE';
    const targets = isMovie ? cinemas : arenas;
    const layout = isMovie ? CINEMA_LAYOUT : ARENA_LAYOUT;
    for (let day = 1; day <= DAYS; day++) {
      for (const venue of targets) {
        const daySlots = isMovie ? slots.filter((_, i) => (i + day + venue.name.length) % 2 === 0) : day % 2 ? [[19, 30]] : [];
        for (const [h, m] of daySlots) {
          await post('/api/v1/catalog/shows', {
            eventId: event.id,
            venueId: venue.id,
            startTime: startTime(day, h, m),
            currency: 'INR',
            maxSeatsPerBooking: isMovie ? 8 : 6,
            ...layout,
          }, accessToken);
          shows++;
        }
      }
    }
  }
  console.log(`Done: ${venues.length} venues, ${events.length} events, ${shows} shows. Seat maps appear within a few seconds.`);
}

main().catch((err) => {
  console.error(`Seeding failed: ${err.message}`);
  console.error('Is the stack up?  docker compose up -d --build   (gateway :8080, keycloak :8180)');
  process.exit(1);
});
